                            origin: .inlineChoiceResponse,
                            speakerID: StoryActorID.seedSteward,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "筐给我。熟的摘，青的别碰。谁敢硬拽藤，我拍他手。",
                            portraitID: StoryActorID.seedSteward,
                            condition: .selectedChoice(.harvest, arcID: .q02),
                            blockingCueID: "brookseed.story.q02.cue.blk_03",
                            visibility: .ordinary
