                            origin: .manuscript,
                            speakerID: StoryActorID.neighborConsensus,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "你过来。就站我旁边吧，中间那块泥少一点。",
                            portraitID: StoryActorID.neighborConsensus,
                            condition: .always,
                            blockingCueID: "brookseed.story.q02.cue.blk_04",
                            visibility: .ordinary
                        ),
                    ],
                    choices: [],
                    nextStageIDs: []
                ),
                StoryStageDefinition(
                    id: "brookseed.story.q02.stage.reveal_callback",
