                            speakerID: StoryActorID.neighborStoryteller,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "‘大家听农场主的’排过三遍。真下雨那晚，涧麦婶还是喊早了一句。",
                            portraitID: StoryActorID.neighborStoryteller,
                            condition: .always,
                            blockingCueID: "brookseed.story.q02.cue.blk_05",
                            visibility: .finaleOnly
                        ),
                    ],
                    choices: [],
                    nextStageIDs: []
                ),
            ],
            branchChoices: StoryChoiceID.choices(for: .q02)
        ),
        StoryDefinition(
            id: .q03,
            title: "一篮铃花莓的三种说法",
            stages: [
                StoryStageDefinition(
