                            origin: .manuscript,
                            speakerID: StoryActorID.neighborConsensus,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "刚有人问‘是不是东坡那家农场的’。你看，他们记住地方了。",
                            portraitID: StoryActorID.neighborConsensus,
                            condition: .always,
                            blockingCueID: "brookseed.story.q03.cue.blk_01",
                            visibility: .ordinary
