                            origin: .manuscript,
                            speakerID: StoryActorID.neighborStoryteller,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "烧焦的纸、断铃铛、雾岭。平时我写成这样，会被你们说太假。可东西都在这儿。",
                            portraitID: StoryActorID.neighborStoryteller,
                            condition: .always,
                            blockingCueID: "brookseed.story.q08.cue.blk_01",
                            visibility: .ordinary
                        ),
                    ],
                    choices: [],
                    nextStageIDs: ["brookseed.story.q08.stage.warning_2"]
