                            origin: .manuscript,
                            speakerID: StoryActorID.neighborEvidence,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "这页契约用了两种墨，中间还跳了一页。东西不全，但灰栅的印是真的。",
                            portraitID: StoryActorID.neighborEvidence,
