                            origin: .manuscript,
                            speakerID: StoryActorID.neighborConsensus,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "别现在就往外跑。先回去换双鞋，吃点东西。今天走、明早走，都来得及。",
                            portraitID: StoryActorID.neighborConsensus,
                            condition: .always,
                            blockingCueID: "brookseed.story.q08.cue.blk_01",
