                            origin: .manuscript,
                            speakerID: StoryActorID.waterApprentice,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "我没抢……行，晚闸给他。我看早上。",
                            portraitID: StoryActorID.waterApprentice,
                            condition: .always,
