                            speakerID: StoryActorID.neighborHearsay,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "我住你这儿两晚。谁来找你，我记名字，不替他编下半句。茶嘛，回来现烧。",
                            portraitID: StoryActorID.neighborHearsay,
