                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "轮班表塞你门后了。你别半路惦记牛吃没吃，它今天吃得比你多。",
                            portraitID: StoryActorID.neighborConsensus,
                            condition: .always,
                            blockingCueID: "brookseed.story.q08.cue.blk_02",
                            visibility: .ordinary
