                            origin: .manuscript,
                            speakerID: StoryActorID.system,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "订单、报价和剧情截止暂停。货币、背包物品、种子与任务物品不会消耗。",
                            portraitID: nil,
                            condition: .always,
                            blockingCueID: "brookseed.story.q08.cue.blk_02",
