                            id: "brookseed.story.q08.line.rev_002",
                            sourceID: "Q08_REV_002",
                            origin: .manuscript,
                            speakerID: StoryActorID.bellPrincess,
                            attributedActorID: nil,
                            speakerAnnotation: nil,
                            text: "没人绑我。你到门外时，灰栅还嫌我第二遍喊得不够怕。",
